    {
        // 1. Data Path and File Operation
        string relativePath = "education/student_scores.json";
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData", relativePath);

        JArray studentsData;
        if (File.Exists(dataPath))
        {
            string jsonData = File.ReadAllText(dataPath);
            studentsData = JArray.Parse(jsonData);
        }
        else
        {
            studentsData = new JArray();
        }

        // Check if student S007 already exists; if so, update, otherwise add.
        bool studentExists = false;
        foreach (var student in studentsData)
        {
            if (student["student_id"]?.ToString() == "S007")
            {
                student["math_score"] = 88;
                studentExists = true;
                break;
            }
        }

        if (!studentExists)
        {
            JObject newStudent = new JObject();
            newStudent["student_id"] = "S007";
            newStudent["name"] = "Student S007";
            newStudent["math_score"] = 88;
            newStudent["science_score"] = 75; // Default placeholder
            newStudent["english_score"] = 80; // Default placeholder
            studentsData.Add(newStudent);
        }

        // Save the updated data back to the streaming assets path
        string directory = Path.GetDirectoryName(dataPath);
        if (!Directory.Exists(directory)) Directory.CreateDirectory(directory);
        File.WriteAllText(dataPath, studentsData.ToString());

        // 2. Visualization Generation (Bar Chart)
        GameObject chartObj = new GameObject("MathScoreChart_S007");
        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;

        RectTransform rectTransform = chartObj.GetComponent<RectTransform>();
        rectTransform.sizeDelta = new Vector2(800.00f, 600.00f);

        chartObj.AddComponent<CanvasScaler>();
        chartObj.AddComponent<GraphicRaycaster>();

        BarChart chart = chartObj.AddComponent<BarChart>();
        chart.GetOrAddChartComponent<Title>().text = "Student Math Scores";
        chart.GetOrAddChartComponent<Legend>();
        chart.GetOrAddChartComponent<XAxis>();
        chart.GetOrAddChartComponent<YAxis>();

        // Create the Bar series
        var barSerie = chart.AddSerie<Bar>("Math Score");

        // Define color for the bars (#RRGGBBAA format)
        Color barColor;
        if (ColorUtility.TryParseHtmlString("#58B2DCFF", out barColor))
        {
            barSerie.itemStyle.color = barColor;
        }

        // Load data into the chart
        foreach (var item in studentsData)
        {
            string sId = item["student_id"].ToString();
            float mScore = (float)item["math_score"];
            chart.AddXAxisData(sId);
            chart.AddData(0, mScore);
        }

        // 3. Physical Placement and Orientation
        // User status: Pos(0, 1.7, 0), Forward(0, 0, -1). 
        // Placing the chart 2.0m in front of the user (at Z = -2.0)
        chartObj.transform.position = new Vector3(0.00f, 1.50f, -2.00f);

        // Rotate to face the user. Since the chart is at Z=-2 and user is at Z=0, chart's forward should be +Z.
        chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0.00f, 0.00f, 1.00f));

        // Set a reasonable scale for world space (UI is 800px wide, so 0.002f makes it 1.6m wide)
        chartObj.transform.localScale = new Vector3(0.0025f, 0.0025f, 0.0025f);
