using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Define the chart names to be arranged
        string[] chartNames = { "MathScoreChart", "ScienceScoreChart", "EnglishScoreChart" };

        // 2. Extract user status for positioning
        // Position: (0.00, 1.70, 0.00), Forward: (0.00, 0.00, -1.00), Right: (-1.00, 0.00, 0.00)
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 userForward = new Vector3(0.00f, 0.00f, -1.00f);
        Vector3 userRight = new Vector3(-1.00f, 0.00f, 0.00f);

        // 3. Layout Parameters
        float radius = 3.00f;       // Distance from user
        float chartHeight = 2.00f;  // Consistent height for all charts
        float angleSpread = 30.00f; // Angle between each chart in degrees

        // 4. Arrange each chart
        for (int i = 0; i < chartNames.Length; i++)
        {
            GameObject chartObj = GameObject.Find(chartNames[i]);

            if (chartObj != null)
            {
                // Calculate the angle for this specific chart
                // i=0 -> -30 degrees (Left), i=1 -> 0 degrees (Center), i=2 -> 30 degrees (Right)
                float angleDegrees = (i - 1) * angleSpread;
                float angleRadians = angleDegrees * Mathf.Deg2Rad;

                // Calculate position on the arc relative to user forward and right vectors
                // Vector = Forward * cos(theta) + Right * sin(theta)
                Vector3 direction = (userForward * Mathf.Cos(angleRadians)) + (userRight * Mathf.Sin(angleRadians));
                Vector3 newPosition = userPos + direction * radius;

                // Set the height specifically
                newPosition.y = chartHeight;

                // Apply transformation
                chartObj.transform.position = newPosition;

                // Rotate to face the user
                // For UI/Charts in Unity, the forward vector (Z+) usually points away from the viewer
                Vector3 lookDirection = (newPosition - userPos).normalized;
                chartObj.transform.rotation = Quaternion.LookRotation(lookDirection);
            }
            else
            {
                Debug.LogWarning("Chart not found: " + chartNames[i]);
            }
        }
    }
}

