            int row = index / columns;
            int col = index % columns;

            Vector3 offset = new Vector3(col * xSpacing, -row * ySpacing, 0);
            chartObj.transform.position = startPos + offset;

            // Face the user (user is looking at -z, so charts should face +z)
            chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0, 0, 1));

            index++;
        }
    }
