        // User is at (0.0, 1.7, 0.0)
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 directionToUser = userPos - chartPosition;
        directionToUser.y = 0; // Keep the chart level/upright
        if (directionToUser != Vector3.zero)
        {
            chartObj.transform.rotation = Quaternion.LookRotation(directionToUser);
        }

        // 6. Setup DxR Visualization Component
        Vis vis = chartObj.AddComponent<Vis>();

        // 7. Define the 3D Visualization Specification (JSON)
        // We use a "bar" mark, mapping 'time' to X and 'electricity' to Y (height).
        // Colors are required to be 8-character hex strings.
        string spec = "{" +
            "\"data\": {\"values\": " + jsonData + "}," +
            "\"mark\": \"bar\"," +
            "\"encoding\": {" +
                "\"x\": {\"field\": \"time\", \"type\": \"nominal\"}," +
                "\"y\": {\"field\": \"electricity\", \"type\": \"quantitative\"}," +
                "\"z\": {\"value\": 0}," +
                "\"color\": {\"value\": \"#00FFFFFF\"}" +
            "}" +
        "}";

        // Apply the specification to the Vis component
        vis.UpdateVis(spec);

        // 8. Adjust Scale
        // The building width is 2m, we scale the chart to 1.5m wide (scale 1.5) to fit well.
        chartObj.transform.localScale = new Vector3(1.50f, 1.50f, 1.50f);
    }
}

