        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found at: " + dataPath);
            return;
        }

        string jsonData = File.ReadAllText(dataPath);
        JArray students = JArray.Parse(jsonData);

        // 2. Layout Parameters
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 spawnCenter = new Vector3(0.00f, 1.50f, -2.50f); // 2.5m in front of user
        float spacing = 1.20f; // Distance between charts
        int count = students.Count;
        float startX = -(count - 1) * spacing / 2.0f;

        // 3. Generate a chart for each student
        for (int i = 0; i < count; i++)
        {
            JToken student = students[i];
            string studentName = student["name"].ToString();
            string studentId = student["student_id"].ToString();
