            rectTransform.sizeDelta = new Vector2(500f, 400f);
            chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

            // Positioning
            float posX = startX + (i * spacing);
            chartObj.transform.position = new Vector3(posX, 1.50f, -2.50f);
            chartObj.transform.rotation = Quaternion.LookRotation(chartObj.transform.position - userPos);

