            serie.itemStyle.color = new Color32(84, 112, 198, 255); // #5470C6FF

            // Add values
            chart.AddData(0, (float)student["math_score"]);
            chart.AddData(0, (float)student["science_score"]);
            chart.AddData(0, (float)student["english_score"]);

            // Ensure Tooltip and Legend are handled
            chart.GetOrAddChartComponent<Legend>().show = false;
            chart.GetOrAddChartComponent<Tooltip>().show = true;
        }
    }
